package com.zying.zysu.ui.sumh.util

import com.google.gson.JsonObject
import org.junit.Test
import kotlin.test.*

/** Inputs are generated by production native parser/store/diff with real mbedTLS SHA256. */
class SUMHProfilesNativeFixturesTest {
    private fun bytes(file: String) = requireNotNull(javaClass.getResourceAsStream("/sumh-profiles-native/$file")).use { it.readBytes() }
    private fun text(file: String) = profileDecode(bytes(file))
    private fun request(name: String): SUMHProfileRequest {
        val root = SUMHProfilesParser.json(text("$name.request.json")); val action = root.get("action").asString
        val input = if (action in SUMH_PROFILE_MUTATIONS) root.getAsJsonObject("input") else root
        fun value(key: String): String? = input.get(key)?.takeUnless { it.isJsonNull }?.asString
        return SUMHProfileRequest(action, value("id"), value("bank_revision"), value("profile_revision"), value("source_id"), value("name"), value("note"),
            input.get("profile")?.toString(), root.getAsJsonArray("resources")?.map { raw -> SUMHProfileResource.entries.single { it.wireName == raw.asString } }?.toSet().orEmpty())
    }
    @Test fun everyProductionResponseBindsToItsActualRequest() {
        val index = SUMHProfilesParser.json("{\"pairs\":" + text("index.json") + "}").getAsJsonArray("pairs")
        assertTrue(index.size() >= 23)
        index.forEach { raw -> val item = raw.asJsonObject; val name = item.get("name").asString
            if (name == "capabilities") assertEquals(SUMH_PROFILE_ACTIONS, SUMHProfilesParser.capabilities(bytes("$name.response.json")).actions)
            else {
                val result = SUMHProfilesParser.result(bytes("$name.response.json"), request(name))
                val expected = if (name == "capture-namespace-restore-failure") "unknown" else item.get("status").asString
                assertEquals(expected, result.status, name)
                assertEquals(request(name).id, result.id, name)
                if (expected in setOf("stale", "not_saved")) { assertFalse(result.unknown, name); assertFalse(result.complete, name) }
            }
        }
    }
    @Test fun productionCanonicalBytesAndDomainRevisionMatchForUnicodeAndControls() {
        for (name in listOf("default", "unicode")) {
            val canonical = text("$name.profile.json").removeSuffix("\n")
            val document = SUMHProfilesParser.document(canonical)
            assertEquals(canonical + "\n", document.text, name)
            assertEquals(text("$name.revision.txt").trim(), SUMHProfilesParser.revision(document), name)
        }
        val unicode = SUMHProfilesParser.document(text("unicode.profile.json"))
        assertEquals(2, unicode.resourceCounts[SUMHProfileResource.Modules]); assertEquals(2, unicode.resourceCounts[SUMHProfileResource.UserHide])
        assertContains(unicode.note, "\b\u000c\n\r\t/\\\"")
        val rules = SUMHProfilesParser.json(unicode.text).getAsJsonObject("resources").getAsJsonObject("user_hide").getAsJsonArray("rules")
        assertEquals("b".repeat(32), rules[0].asJsonObject.get("id").asString)
    }
    @Test fun productionHideIdentityConflictsAndMapEnabledDifferenceRemainDistinct() {
        val result = SUMHProfilesParser.result(bytes("import-preview-hide-conflicts.response.json"), request("import-preview-hide-conflicts"))
        val hidden = result.diff!!.resources.single { it.resource == SUMHProfileResource.UserHide }
        assertEquals(2, hidden.identityConflicts.size); assertEquals(1, hidden.added); assertEquals(1, hidden.removed); assertEquals(1, hidden.changed)
        assertEquals(1, result.diff.resources.single { it.resource == SUMHProfileResource.Maps }.enabledChanges.size)
    }
    @Test fun successfulMutationRequiresExactPreviousRevisionAndResultShape() {
        val original = SUMHProfilesParser.json(text("capture-default.response.json")); val expectedRequest = request("capture-default")
        fun rejected(change: (JsonObject) -> Unit) {
            val value = original.deepCopy().also(change)
            assertFails { SUMHProfilesParser.result(profileUtf8(value.toString()), expectedRequest) }
        }
        rejected { it.remove("previous_bank_revision") }
        rejected { it.addProperty("previous_bank_revision", "sha256-v1:" + "0".repeat(64)) }
        rejected { it.add("profile_revision", com.google.gson.JsonNull.INSTANCE) }
        val remove = SUMHProfilesParser.json(text("remove-clone.response.json"))
        remove.addProperty("profile_revision", text("unicode.revision.txt").trim())
        assertFails { SUMHProfilesParser.result(profileUtf8(remove.toString()), request("remove-clone")) }
    }
    @Test fun unchangedBindsBothBankAndExistingProfileRevision() {
        val value = SUMHProfilesParser.json(text("rename-unchanged.response.json")); val request = request("rename-unchanged")
        val parsed = SUMHProfilesParser.result(profileUtf8(value.toString()), request)
        assertTrue(parsed.saved); assertFalse(parsed.durabilityConfirmed)
        value.addProperty("bank_revision", "sha256-v1:" + "0".repeat(64))
        assertFails { SUMHProfilesParser.result(profileUtf8(value.toString()), request) }
    }
    @Test fun pathologicalNumberCannotExpandBeyondRawByteBudget() {
        assertFails { SUMHProfilesParser.json("{\"x\":1e999999999}") }
        assertFails { SUMHProfilesParser.json("{\"x\":1e-999999999}") }
        assertFails { SUMHProfilesParser.json("{\"x\":123456789012345678901234567890}") }
    }
    @Test fun foreignActionPayloadCannotHideInsideSuccessfulEnvelope() {
        val listing = SUMHProfilesParser.json(text("empty-list.response.json"))
        listing.add("profile", SUMHProfilesParser.json(text("default.profile.json")))
        assertFails { SUMHProfilesParser.result(profileUtf8(listing.toString()), request("empty-list")) }
        val mutation = SUMHProfilesParser.json(text("capture-default.response.json"))
        mutation.remove("requested_action"); mutation.addProperty("kind", "sumh.profile.result"); mutation.addProperty("action", "capture")
        mutation.addProperty("can_activate", false); mutation.addProperty("global_atomic", false); mutation.addProperty("runtime_evaluated", false)
        assertFails { SUMHProfilesParser.result(profileUtf8(mutation.toString()), request("capture-default")) }
    }
}
